{
  "name": "EcoGuard - Gestão Ambiental",
  "description": "Sistema de controle de obrigações ambientais com rastreamento de prazos, órgãos reguladores e status de conformidade para múltiplos empreendimentos."
}

export enum Status {
  VIGENTE = 'VIGENTE',
  PENDENTE = 'PENDENTE',
  EM_ANDAMENTO = 'EM ANDAMENTO',
  CONCLUIDO = 'CONCLUÍDO'
}

export enum Empresa {
  CAMPLUVAS = 'CAMPLUVAS',
  LOCATEX = 'LOCATEX'
}

export interface Obligation {
  id: string;
  periodicidade: string;
  dataInicio: string;
  dataFinal: string;
  orgao: string;
  tipo: string;
  numeroDocumento: string;
  validadeDocumento: string;
  nomeDocumento: string;
  empresa: Empresa;
  acao: string;
  status: Status;
  observacoes: string;
  createdAt: number;
}

export type NewObligation = Omit<Obligation, 'id' | 'createdAt'>;

import { Status, Empresa } from './types';

export const INITIAL_PERIODICITIES = [
  'Mensal',
  'Trimestral',
  'Semestral',
  'Anual',
  'Bienal',
  'Única'
];

export const INITIAL_ORGAOS = [
  'IBAMA',
  'CETESB',
  'INEA',
  'SEMAD',
  'Prefeitura Municipal'
];

export const STATUS_COLORS: Record<Status, string> = {
  [Status.VIGENTE]: 'bg-green-500',
  [Status.PENDENTE]: 'bg-red-500',
  [Status.EM_ANDAMENTO]: 'bg-yellow-500',
  [Status.CONCLUIDO]: 'bg-blue-500',
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { 
  ClipboardCheck, 
  LayoutDashboard, 
  PlusCircle, 
  ListTodo,
  ShieldCheck,
  Menu,
  X
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import ObligationForm from './components/ObligationForm';
import ObligationList from './components/ObligationList';
import { Obligation } from './types';

const App: React.FC = () => {
  const [obligations, setObligations] = useState<Obligation[]>(() => {
    const saved = localStorage.getItem('eco_obligations');
    return saved ? JSON.parse(saved) : [];
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('eco_obligations', JSON.stringify(obligations));
  }, [obligations]);

  const addObligation = (newObligation: Obligation) => {
    setObligations(prev => [newObligation, ...prev]);
  };

  const deleteObligation = (id: string) => {
    setObligations(prev => prev.filter(o => o.id !== id));
  };

  const updateObligation = (id: string, updated: Partial<Obligation>) => {
    setObligations(prev => prev.map(o => o.id === id ? { ...o, ...updated } : o));
  };

  return (
    <Router>
      <div className="min-h-screen flex flex-col md:flex-row overflow-hidden" style={{ backgroundColor: '#00F3FF' }}>

        {/* Mobile Toggle */}
        <div className="md:hidden bg-black text-white p-4 flex justify-between items-center shadow-lg">
          <div className="flex items-center gap-2">
            <ShieldCheck className="text-[#00F3FF]" />
            <span className="font-bold tracking-tight">EcoGuard SGA</span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
            {isSidebarOpen ? <X /> : <Menu />}
          </button>
        </div>

        {/* Sidebar */}
        <aside className={`
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
          md:translate-x-0 fixed md:static inset-y-0 left-0 z-50
          w-64 bg-black text-white transition-transform duration-300 ease-in-out
          flex flex-col shadow-2xl border-r border-[#00F3FF]/20
        `}>
          <div className="p-8 hidden md:flex flex-col items-center border-b border-[#00F3FF]/10">
            <div className="bg-[#00F3FF] p-3 rounded-2xl mb-4">
              <ShieldCheck className="w-8 h-8 text-black" />
            </div>
            <h1 className="text-xl font-black italic tracking-tighter">ECOGUARD</h1>
            <p className="text-[10px] text-gray-400 font-medium tracking-[0.2em] uppercase">Gestão Ambiental</p>
          </div>

          <nav className="flex-1 p-6 space-y-4">
            <Link 
              to="/" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#00F3FF]/10 hover:text-[#00F3FF] transition-all group"
            >
              <LayoutDashboard className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Dashboard</span>
            </Link>
            <Link 
              to="/cadastro" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#00F3FF]/10 hover:text-[#00F3FF] transition-all group"
            >
              <PlusCircle className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Nova Obrigação</span>
            </Link>
            <Link 
              to="/listagem" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#00F3FF]/10 hover:text-[#00F3FF] transition-all group"
            >
              <ListTodo className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Obrigações</span>
            </Link>
          </nav>

          <div className="p-6 text-center text-[10px] text-gray-500">
            v1.0.4 &copy; {new Date().getFullYear()} EcoGuard
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-6xl mx-auto">
            <Routes>
              <Route path="/" element={<Dashboard obligations={obligations} />} />
              <Route path="/cadastro" element={<ObligationForm onSave={addObligation} />} />
              <Route path="/listagem" element={<ObligationList obligations={obligations} onDelete={deleteObligation} onUpdate={updateObligation} />} />
            </Routes>
          </div>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Save, Plus, X } from 'lucide-react';
import { Obligation, Status, Empresa } from '../types';
import { INITIAL_ORGAOS, INITIAL_PERIODICITIES } from '../constants';

interface ObligationFormProps {
  onSave: (obligation: Obligation) => void;
}

const ObligationForm: React.FC<ObligationFormProps> = ({ onSave }) => {
  const navigate = useNavigate();
  const [periodicities, setPeriodicities] = useState(INITIAL_PERIODICITIES);
  const [orgaos, setOrgaos] = useState(INITIAL_ORGAOS);
  const [showAddPeriodicidade, setShowAddPeriodicidade] = useState(false);
  const [showAddOrgao, setShowAddOrgao] = useState(false);
  const [newItemValue, setNewItemValue] = useState('');

  const [formData, setFormData] = useState({
    periodicidade: periodicities[0],
    dataInicio: '',
    dataFinal: '',
    orgao: orgaos[0],
    tipo: '',
    numeroDocumento: '',
    validadeDocumento: '',
    nomeDocumento: '',
    empresa: Empresa.CAMPLUVAS,
    acao: '',
    status: Status.PENDENTE,
    observacoes: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleAddNewItem = (type: 'periodicidade' | 'orgao') => {
    if (!newItemValue.trim()) return;

    if (type === 'periodicidade') {
      setPeriodicities(prev => [...prev, newItemValue]);
      setFormData(prev => ({ ...prev, periodicidade: newItemValue }));
      setShowAddPeriodicidade(false);
    } else {
      setOrgaos(prev => [...prev, newItemValue]);
      setFormData(prev => ({ ...prev, orgao: newItemValue }));
      setShowAddOrgao(false);
    }
    setNewItemValue('');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newObligation: Obligation = {
      ...formData,
      id: crypto.randomUUID(),
      createdAt: Date.now()
    };
    onSave(newObligation);
    navigate('/listagem');
  };

  const inputClass = "w-full bg-black text-white border-2 border-transparent focus:border-[#00F3FF] p-3 rounded-lg outline-none transition-all placeholder-gray-500";
  const labelClass = "block text-[11px] font-bold uppercase tracking-wider mb-2 text-black/80";

  return (
    <div className="bg-white/40 backdrop-blur-md rounded-3xl p-6 md:p-10 shadow-xl border border-white/50 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-3xl font-black italic text-black uppercase tracking-tighter">CADASTRO DE OBRIGAÇÕES</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

          {/* Periodicidade */}
          <div className="relative">
            <label className={labelClass}>Periodicidade</label>
            <div className="flex gap-2">
              <select 
                name="periodicidade" 
                value={formData.periodicidade} 
                onChange={handleChange}
                className={inputClass}
              >
                {periodicities.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
              <button 
                type="button"
                onClick={() => setShowAddPeriodicidade(true)}
                className="bg-black text-[#00F3FF] p-3 rounded-lg hover:bg-gray-900 transition-colors"
                title="Cadastrar Periodicidade"
              >
                <Plus size={20} />
              </button>
            </div>
          </div>

          {/* Orgão */}
          <div className="relative">
            <label className={labelClass}>Órgão</label>
            <div className="flex gap-2">
              <select 
                name="orgao" 
                value={formData.orgao} 
                onChange={handleChange}
                className={inputClass}
              >
                {orgaos.map(o => <option key={o} value={o}>{o}</option>)}
              </select>
              <button 
                type="button"
                onClick={() => setShowAddOrgao(true)}
                className="bg-black text-[#00F3FF] p-3 rounded-lg hover:bg-gray-900 transition-colors"
                title="Cadastrar Órgão"
              >
                <Plus size={20} />
              </button>
            </div>
          </div>

          {/* Empresa */}
          <div>
            <label className={labelClass}>Empresa</label>
            <select name="empresa" value={formData.empresa} onChange={handleChange} className={inputClass}>
              <option value={Empresa.CAMPLUVAS}>CAMPLUVAS</option>
              <option value={Empresa.LOCATEX}>LOCATEX</option>
            </select>
          </div>

          {/* Datas */}
          <div>
            <label className={labelClass}>Início das Providências</label>
            <input type="date" name="dataInicio" value={formData.dataInicio} onChange={handleChange} className={inputClass} required />
          </div>
          <div>
            <label className={labelClass}>Final das Providências</label>
            <input type="date" name="dataFinal" value={formData.dataFinal} onChange={handleChange} className={inputClass} required />
          </div>
          <div>
            <label className={labelClass}>Validade do Documento</label>
            <input type="date" name="validadeDocumento" value={formData.validadeDocumento} onChange={handleChange} className={inputClass} required />
          </div>

          {/* Texto */}
          <div>
            <label className={labelClass}>Tipo</label>
            <input type="text" name="tipo" value={formData.tipo} onChange={handleChange} className={inputClass} placeholder="Ex: Licença Operação" />
          </div>
          <div>
            <label className={labelClass}>Nº do Documento</label>
            <input type="text" name="numeroDocumento" value={formData.numeroDocumento} onChange={handleChange} className={inputClass} placeholder="Ex: 001/2024" />
          </div>
          <div>
            <label className={labelClass}>Nome do Documento</label>
            <input type="text" name="nomeDocumento" value={formData.nomeDocumento} onChange={handleChange} className={inputClass} placeholder="Nome amigável" />
          </div>

          {/* Ação e Status */}
          <div className="md:col-span-2">
            <label className={labelClass}>Ação</label>
            <input type="text" name="acao" value={formData.acao} onChange={handleChange} className={inputClass} placeholder="Descreva a ação necessária" />
          </div>
          <div>
            <label className={labelClass}>Status</label>
            <select name="status" value={formData.status} onChange={handleChange} className={inputClass}>
              <option value={Status.VIGENTE}>VIGENTE</option>
              <option value={Status.PENDENTE}>PENDENTE</option>
              <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
              <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
            </select>
          </div>
        </div>

        {/* Observações */}
        <div>
          <label className={labelClass}>Observações</label>
          <textarea 
            name="observacoes" 
            value={formData.observacoes} 
            onChange={handleChange} 
            className={`${inputClass} min-h-[120px] resize-none`}
            placeholder="Informações adicionais relevantes..."
          />
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button 
            type="button" 
            onClick={() => navigate('/listagem')}
            className="px-6 py-3 font-bold text-black border-2 border-black rounded-xl hover:bg-black/5 transition-colors"
          >
            Cancelar
          </button>
          <button 
            type="submit"
            className="px-10 py-3 bg-black text-[#00F3FF] font-black italic rounded-xl hover:shadow-[0_0_20px_rgba(0,243,255,0.4)] transition-all flex items-center gap-2"
          >
            <Save size={20} />
            SALVAR OBRIGAÇÃO
          </button>
        </div>
      </form>

      {/* Modals for Dynamic Entry */}
      {(showAddPeriodicidade || showAddOrgao) && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-8 w-full max-w-sm shadow-2xl animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-black mb-4 uppercase tracking-tighter italic">
              Cadastrar {showAddPeriodicidade ? 'Periodicidade' : 'Órgão'}
            </h3>
            <input 
              autoFocus
              type="text" 
              value={newItemValue}
              onChange={(e) => setNewItemValue(e.target.value)}
              className="w-full bg-black text-white p-3 rounded-lg mb-6 outline-none"
              placeholder="Digite o novo valor..."
              onKeyDown={(e) => e.key === 'Enter' && handleAddNewItem(showAddPeriodicidade ? 'periodicidade' : 'orgao')}
            />
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => { setShowAddPeriodicidade(false); setShowAddOrgao(false); setNewItemValue(''); }}
                className="px-4 py-2 font-bold text-gray-500 hover:text-black transition-colors"
              >
                Fechar
              </button>
              <button 
                onClick={() => handleAddNewItem(showAddPeriodicidade ? 'periodicidade' : 'orgao')}
                className="px-6 py-2 bg-black text-[#00F3FF] font-black rounded-lg"
              >
                ADICIONAR
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ObligationForm;

import React, { useState } from 'react';
import { 
  Search, 
  Trash2, 
  ChevronRight, 
  Calendar, 
  Building2, 
  AlertCircle,
  FileText,
  Filter
} from 'lucide-react';
import { Obligation, Status, Empresa } from '../types';
import { STATUS_COLORS } from '../constants';

interface ObligationListProps {
  obligations: Obligation[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, updated: Partial<Obligation>) => void;
}

const ObligationList: React.FC<ObligationListProps> = ({ obligations, onDelete, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterEmpresa, setFilterEmpresa] = useState<Empresa | 'TODAS'>('TODAS');
  const [filterStatus, setFilterStatus] = useState<Status | 'TODOS'>('TODOS');

  const filtered = obligations.filter(o => {
    const matchesSearch = o.nomeDocumento.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          o.orgao.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          o.numeroDocumento.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesEmpresa = filterEmpresa === 'TODAS' || o.empresa === filterEmpresa;
    const matchesStatus = filterStatus === 'TODOS' || o.status === filterStatus;
    return matchesSearch && matchesEmpresa && matchesStatus;
  });

  const formatDate = (dateStr: string) => {
    if (!dateStr) return 'N/A';
    return new Date(dateStr).toLocaleDateString('pt-BR');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white/20 p-4 rounded-2xl backdrop-blur-sm">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-black/60 w-5 h-5" />
          <input 
            type="text"
            placeholder="Buscar por documento, órgão..."
            className="w-full pl-10 pr-4 py-3 bg-white/80 rounded-xl outline-none focus:ring-2 ring-black transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex gap-3 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
          <select 
            className="bg-black text-white px-4 py-3 rounded-xl outline-none"
            value={filterEmpresa}
            onChange={(e) => setFilterEmpresa(e.target.value as any)}
          >
            <option value="TODAS">TODAS AS EMPRESAS</option>
            <option value={Empresa.CAMPLUVAS}>CAMPLUVAS</option>
            <option value={Empresa.LOCATEX}>LOCATEX</option>
          </select>

          <select 
            className="bg-black text-white px-4 py-3 rounded-xl outline-none"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
          >
            <option value="TODOS">TODOS STATUS</option>
            <option value={Status.VIGENTE}>VIGENTE</option>
            <option value={Status.PENDENTE}>PENDENTE</option>
            <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
            <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
          </select>
        </div>
      </div>

      <div className="grid gap-4">
        {filtered.length === 0 ? (
          <div className="bg-white/40 p-12 rounded-3xl text-center border-2 border-dashed border-black/10">
            <AlertCircle className="w-12 h-12 text-black/40 mx-auto mb-4" />
            <p className="text-xl font-bold text-black/60 italic">Nenhuma obrigação encontrada</p>
          </div>
        ) : (
          filtered.map(o => (
            <div 
              key={o.id} 
              className="bg-white rounded-3xl p-6 shadow-sm border border-transparent hover:border-black/10 transition-all group overflow-hidden relative"
            >
              {/* Sidebar color */}
              <div className={`absolute left-0 top-0 bottom-0 w-2 ${STATUS_COLORS[o.status]}`} />

              <div className="flex flex-col lg:flex-row justify-between gap-6">
                <div className="flex-1 space-y-4">
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <span className={`text-[10px] font-black px-2 py-0.5 rounded text-white ${STATUS_COLORS[o.status]}`}>
                          {o.status}
                        </span>
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{o.periodicidade}</span>
                      </div>
                      <h3 className="text-xl font-black italic text-black uppercase">{o.nomeDocumento}</h3>
                      <p className="text-sm font-medium text-gray-500">{o.tipo} - {o.numeroDocumento}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><Building2 size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Órgão / Empresa</p>
                        <p className="font-bold text-black truncate">{o.orgao} / {o.empresa}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><Calendar size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Providências</p>
                        <p className="font-bold text-black">{formatDate(o.dataInicio)} - {formatDate(o.dataFinal)}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><AlertCircle size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Validade</p>
                        <p className="font-bold text-black">{formatDate(o.validadeDocumento)}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><FileText size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Ação</p>
                        <p className="font-bold text-black truncate max-w-[150px]">{o.acao}</p>
                      </div>
                    </div>
                  </div>

                  {o.observacoes && (
                    <div className="mt-4 p-4 bg-gray-50 rounded-2xl border-l-4 border-black/10">
                      <p className="text-xs font-bold text-gray-400 uppercase mb-1">Observações</p>
                      <p className="text-sm text-gray-700">{o.observacoes}</p>
                    </div>
                  )}
                </div>

                <div className="flex flex-row lg:flex-col items-center justify-end gap-2 shrink-0">
                  <select 
                    value={o.status}
                    onChange={(e) => onUpdate(o.id, { status: e.target.value as Status })}
                    className="bg-black text-white text-xs font-bold p-3 rounded-xl border-none outline-none appearance-none cursor-pointer"
                  >
                    <option value={Status.VIGENTE}>VIGENTE</option>
                    <option value={Status.PENDENTE}>PENDENTE</option>
                    <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
                    <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
                  </select>

                  <button 
                    onClick={() => {
                      if(confirm('Deseja excluir esta obrigação?')) onDelete(o.id);
                    }}
                    className="p-3 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ObligationList;

import React, { useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { AlertCircle, CheckCircle, Clock, ShieldAlert } from 'lucide-react';
import { Obligation, Status } from '../types';
import { STATUS_COLORS } from '../constants';

interface DashboardProps {
  obligations: Obligation[];
}

const Dashboard: React.FC<DashboardProps> = ({ obligations }) => {
  const stats = useMemo(() => {
    const total = obligations.length;
    const countByStatus = obligations.reduce((acc, curr) => {
      acc[curr.status] = (acc[curr.status] || 0) + 1;
      return acc;
    }, {} as Record<Status, number>);

    return {
      total,
      vigente: countByStatus[Status.VIGENTE] || 0,
      pendente: countByStatus[Status.PENDENTE] || 0,
      emAndamento: countByStatus[Status.EM_ANDAMENTO] || 0,
      concluido: countByStatus[Status.CONCLUIDO] || 0,
    };
  }, [obligations]);

  const chartData = [
    { name: 'Vigente', value: stats.vigente, color: '#10b981' },
    { name: 'Pendente', value: stats.pendente, color: '#ef4444' },
    { name: 'Andamento', value: stats.emAndamento, color: '#eab308' },
    { name: 'Concluído', value: stats.concluido, color: '#3b82f6' },
  ];

  const MetricCard = ({ title, value, icon: Icon, colorClass }: any) => (
    <div className="bg-white rounded-3xl p-6 shadow-sm border border-transparent hover:shadow-xl transition-all">
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-2xl ${colorClass} bg-opacity-20`}>
          <Icon className={colorClass.replace('bg-', 'text-')} />
        </div>
      </div>
      <h3 className="text-4xl font-black italic tracking-tighter text-black">{value}</h3>
      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{title}</p>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard title="Vigentes" value={stats.vigente} icon={CheckCircle} colorClass="bg-green-500" />
        <MetricCard title="Pendentes" value={stats.pendente} icon={ShieldAlert} colorClass="bg-red-500" />
        <MetricCard title="Em Andamento" value={stats.emAndamento} icon={Clock} colorClass="bg-yellow-500" />
        <MetricCard title="Concluídos" value={stats.concluido} icon={AlertCircle} colorClass="bg-blue-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white rounded-[40px] p-8 shadow-sm">
          <h3 className="text-xl font-black italic uppercase tracking-tighter mb-8 border-b-2 border-black/5 pb-4">
            DISTRIBUIÇÃO POR STATUS
          </h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 'bold' }} 
                />
                <YAxis hide />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="value" radius={[8, 8, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white rounded-[40px] p-8 shadow-sm">
          <h3 className="text-xl font-black italic uppercase tracking-tighter mb-8 border-b-2 border-black/5 pb-4">
            VISÃO GERAL
          </h3>
          <div className="flex items-center justify-center h-[300px]">
             {obligations.length > 0 ? (
               <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                    <Pie
                      data={chartData}
                      innerRadius={80}
                      outerRadius={100}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                 </PieChart>
               </ResponsiveContainer>
             ) : (
               <div className="text-center text-gray-300">
                 <ShieldAlert size={64} className="mx-auto mb-4 opacity-20" />
                 <p className="font-bold uppercase tracking-widest text-xs">Sem dados para exibir</p>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
