                      <p className="text-sm text-gray-700">{o.observacoes}</p>
                    </div>
                  )}
                </div>

                <div className="flex flex-row lg:flex-col items-center justify-end gap-2 shrink-0 no-print">
                  <select 
                    value={o.status}
                    onChange={(e) => onUpdate(o.id, { status: e.target.value as Status })}
                    className="bg-black text-white text-xs font-bold p-3 rounded-xl border-none outline-none appearance-none cursor-pointer"
                  >
                    <option value={Status.VIGENTE}>VIGENTE</option>
                    <option value={Status.PENDENTE}>PENDENTE</option>
                    <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
                    <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
                  </select>

                  <button 
                    onClick={() => {
                      if(confirm('Deseja excluir esta obrigação?')) onDelete(o.id);
                    }}
                    className="p-3 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-2xl font-black italic uppercase tracking-tighter">Exportar Relatório</h3>
              <button onClick={() => setShowExportModal(false)} className="p-2 hover:bg-gray-100 rounded-full">
                <X size={24} />
              </button>
            </div>

            <p className="text-sm text-gray-500 mb-6">Selecione o período de vencimento para filtrar os dados do relatório.</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
              <div>
                <label className="block text-[10px] font-bold uppercase mb-2 text-gray-400">Data Inicial</label>
                <input 
                  type="date" 
                  className="w-full bg-black text-white p-3 rounded-xl outline-none focus:ring-2 ring-[#FFA200] transition-all"
                  value={exportRange.start}
                  onChange={(e) => setExportRange(prev => ({ ...prev, start: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold uppercase mb-2 text-gray-400">Data Final</label>
                <input 
                  type="date" 
                  className="w-full bg-black text-white p-3 rounded-xl outline-none focus:ring-2 ring-[#FFA200] transition-all"
                  value={exportRange.end}
                  onChange={(e) => setExportRange(prev => ({ ...prev, end: e.target.value }))}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              <button 
                onClick={handleExportExcel}
                className="flex items-center justify-center gap-3 p-4 bg-green-600 text-white rounded-2xl font-black hover:bg-green-700 transition-all"
              >
                <FileSpreadsheet size={24} />
                EXPORTAR PARA EXCEL (.xlsx)
              </button>
              <button 
                onClick={handleExportPDF}
                className="flex items-center justify-center gap-3 p-4 bg-red-600 text-white rounded-2xl font-black hover:bg-red-700 transition-all"
              >
                <FilePieChart size={24} />
                GERAR RELATÓRIO PDF
              </button>
            </div>

            <button 
              onClick={() => { setExportRange({start: '', end: ''}); handleExportExcel(); }}
              className="w-full mt-4 text-xs font-bold text-gray-400 hover:text-black uppercase underline"
            >
              Exportar todas as obrigações (sem filtro)
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ObligationList;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { AlertCircle, CheckCircle, Clock, ShieldAlert, Trash2, Pencil, Calendar, User } from 'lucide-react';
import { Obligation, Status } from '../types';
import { STATUS_COLORS } from '../constants';
import EditObligationModal from './EditObligationModal';

interface DashboardProps {
  obligations: Obligation[];
  onDelete?: (id: string) => void;
  onUpdate?: (id: string, updated: Partial<Obligation>) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ obligations, onDelete, onUpdate }) => {
  const [editingItem, setEditingItem] = useState<Obligation | null>(null);

  const stats = useMemo(() => {
    const total = obligations.length;
    const countByStatus = obligations.reduce((acc, curr) => {
      acc[curr.status] = (acc[curr.status] || 0) + 1;
      return acc;
    }, {} as Record<Status, number>);

    return {
      total,
      vigente: countByStatus[Status.VIGENTE] || 0,
      pendente: countByStatus[Status.PENDENTE] || 0,
      emAndamento: countByStatus[Status.EM_ANDAMENTO] || 0,
      concluido: countByStatus[Status.CONCLUIDO] || 0,
    };
  }, [obligations]);

  const recentObligations = useMemo(() => {
    return [...obligations]
      .sort((a, b) => new Date(a.dataFinal).getTime() - new Date(b.dataFinal).getTime())
      .slice(0, 3);
  }, [obligations]);

  const chartData = [
    { name: 'Vigente', value: stats.vigente, color: '#10b981' },
    { name: 'Pendente', value: stats.pendente, color: '#ef4444' },
    { name: 'Andamento', value: stats.emAndamento, color: '#eab308' },
    { name: 'Concluído', value: stats.concluido, color: '#3b82f6' },
  ];

  const MetricCard = ({ title, value, icon: Icon, colorClass }: any) => (
    <div className="bg-white rounded-3xl p-6 shadow-sm border border-transparent hover:shadow-xl transition-all">
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-2xl ${colorClass} bg-opacity-20`}>
          <Icon className={colorClass.replace('bg-', 'text-')} />
        </div>
      </div>
      <h3 className="text-4xl font-black italic tracking-tighter text-black">{value}</h3>
      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{title}</p>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard title="Vigentes" value={stats.vigente} icon={CheckCircle} colorClass="bg-green-500" />
        <MetricCard title="Pendentes" value={stats.pendente} icon={ShieldAlert} colorClass="bg-red-500" />
        <MetricCard title="Em Andamento" value={stats.emAndamento} icon={Clock} colorClass="bg-yellow-500" />
        <MetricCard title="Concluídos" value={stats.concluido} icon={AlertCircle} colorClass="bg-blue-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white rounded-[40px] p-8 shadow-sm">
          <h3 className="text-xl font-black italic uppercase tracking-tighter mb-8 border-b-2 border-black/5 pb-4">
            DISTRIBUIÇÃO POR STATUS
          </h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 'bold' }} 
                />
                <YAxis hide />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="value" radius={[8, 8, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white rounded-[40px] p-8 shadow-sm">
          <h3 className="text-xl font-black italic uppercase tracking-tighter mb-8 border-b-2 border-black/5 pb-4">
            VISÃO GERAL
          </h3>
          <div className="flex items-center justify-center h-[300px]">
             {obligations.length > 0 ? (
               <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                    <Pie
                      data={chartData}
                      innerRadius={80}
                      outerRadius={100}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                 </PieChart>
               </ResponsiveContainer>
             ) : (
               <div className="text-center text-gray-300">
                 <ShieldAlert size={64} className="mx-auto mb-4 opacity-20" />
                 <p className="font-bold uppercase tracking-widest text-xs">Sem dados para exibir</p>
               </div>
             )}
          </div>
        </div>
      </div>

      {/* Próximas Obrigações no Dashboard */}
      <div className="bg-white/30 backdrop-blur-md rounded-[40px] p-8 border border-white/20">
        <h3 className="text-xl font-black italic uppercase tracking-tighter mb-6 flex items-center gap-2">
          <Clock className="text-black" />
          PRÓXIMAS OBRIGAÇÕES
        </h3>
        <div className="grid gap-4">
          {recentObligations.map(o => (
            <div key={o.id} className="bg-white rounded-2xl p-5 flex items-center justify-between shadow-sm group hover:shadow-md transition-all">
              <div className="flex items-center gap-4">
                <div className={`w-2 h-10 rounded-full ${STATUS_COLORS[o.status]}`} />
                <div>
                  <h4 className="font-black text-black uppercase text-sm italic">{o.nomeDocumento}</h4>
                  <div className="flex gap-3 mt-1">
                    <span className="text-[10px] flex items-center gap-1 text-gray-500 font-bold">
                      <Calendar size={12} /> {new Date(o.dataFinal).toLocaleDateString('pt-BR')}
                    </span>
                    <span className="text-[10px] flex items-center gap-1 text-gray-500 font-bold">
                      <User size={12} /> {o.responsavel}
                    </span>
                  </div>
                </div>
              </div>

              <div className="flex gap-2">
                <button 
                  onClick={() => setEditingItem(o)}
                  className="p-2 bg-gray-100 text-gray-600 rounded-lg hover:bg-black hover:text-[#FFA200] transition-all"
                  title="Editar"
                >
                  <Pencil size={16} />
                </button>
                <button 
                  onClick={() => {
                    if(confirm('Confirmar exclusão desta obrigação?')) onDelete?.(o.id);
                  }}
                  className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"
                  title="Excluir"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          ))}
          {obligations.length === 0 && (
            <p className="text-center py-4 text-gray-500 font-bold uppercase text-xs">Nenhuma obrigação pendente</p>
          )}
        </div>
      </div>

      {editingItem && onUpdate && (
        <EditObligationModal 
          obligation={editingItem} 
          onClose={() => setEditingItem(null)} 
          onSave={(updated) => {
            onUpdate(editingItem.id, updated);
            setEditingItem(null);
          }} 
        />
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { 
  Search, 
  Trash2, 
  Calendar, 
  Building2, 
  AlertCircle,
  FileText,
  CheckCircle2,
  User,
  Download,
  X,
  FileSpreadsheet,
  FilePieChart,
  Pencil
} from 'lucide-react';
import { Obligation, Status, Empresa } from '../types';
import { STATUS_COLORS } from '../constants';
import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import EditObligationModal from './EditObligationModal';

interface ObligationListProps {
  obligations: Obligation[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, updated: Partial<Obligation>) => void;
}

const ObligationList: React.FC<ObligationListProps> = ({ obligations, onDelete, onUpdate }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterEmpresa, setFilterEmpresa] = useState<Empresa | 'TODAS'>('TODAS');
  const [filterStatus, setFilterStatus] = useState<Status | 'TODOS'>('TODOS');
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportRange, setExportRange] = useState({ start: '', end: '' });
  const [editingItem, setEditingItem] = useState<Obligation | null>(null);

  const filtered = obligations.filter(o => {
    const matchesSearch = o.nomeDocumento.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          o.orgao.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          o.numeroDocumento.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          (o.responsavel && o.responsavel.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesEmpresa = filterEmpresa === 'TODAS' || o.empresa === filterEmpresa;
    const matchesStatus = filterStatus === 'TODOS' || o.status === filterStatus;
    return matchesSearch && matchesEmpresa && matchesStatus;
  });

  const formatDate = (dateStr: string) => {
    if (!dateStr) return 'N/A';
    return new Date(dateStr).toLocaleDateString('pt-BR');
  };

  const getExportData = () => {
    return obligations.filter(o => {
      if (!exportRange.start || !exportRange.end) return true;
      const date = new Date(o.dataFinal);
      const start = new Date(exportRange.start);
      const end = new Date(exportRange.end);
      return date >= start && date <= end;
    });
  };

  const handleExportExcel = () => {
    const data = getExportData();
    const worksheet = XLSX.utils.json_to_sheet(data.map(o => ({
      'Periodicidade': o.periodicidade,
      'Órgão': o.orgao,
      'Empresa': o.empresa,
      'Início Providências': formatDate(o.dataInicio),
      'Final Providências': formatDate(o.dataFinal),
      'Validade': formatDate(o.validadeDocumento),
      'Tipo': o.tipo,
      'Nº Documento': o.numeroDocumento,
      'Nome Documento': o.nomeDocumento,
      'Responsável': o.responsavel,
      'Ação': o.acao,
      'Status': o.status,
      'Conclusão': formatDate(o.dataConclusao),
      'Observações': o.observacoes
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Obrigações');
    XLSX.writeFile(workbook, `Relatorio_Obrigacoes_${new Date().toISOString().split('T')[0]}.xlsx`);
    setShowExportModal(false);
  };

  const handleExportPDF = () => {
    const data = getExportData();
    const doc = new jsPDF('l', 'mm', 'a4');

    doc.setFontSize(18);
    doc.text('Relatório de Obrigações Ambientais - EcoGuard', 14, 15);
    doc.setFontSize(10);
    doc.text(`Período: ${exportRange.start ? formatDate(exportRange.start) : 'Início'} até ${exportRange.end ? formatDate(exportRange.end) : 'Fim'}`, 14, 22);

    const tableData = data.map(o => [
      o.nomeDocumento,
      o.orgao,
      o.empresa,
      formatDate(o.dataFinal),
      o.responsavel,
      o.status
    ]);

    (doc as any).autoTable({
      startY: 28,
      head: [['Documento', 'Órgão', 'Empresa', 'Vencimento', 'Responsável', 'Status']],
      body: tableData,
      theme: 'grid',
      headStyles: { fillStyle: 'DF', fillColor: [0, 0, 0], textColor: [255, 162, 0] },
      styles: { fontSize: 8 }
    });

    doc.save(`Relatorio_EcoGuard_${new Date().toISOString().split('T')[0]}.pdf`);
    setShowExportModal(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white/20 p-4 rounded-2xl backdrop-blur-sm no-print">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-black/60 w-5 h-5" />
          <input 
            type="text"
            placeholder="Buscar por documento, órgão, responsável..."
            className="w-full pl-10 pr-4 py-3 bg-white/80 rounded-xl outline-none focus:ring-2 ring-black transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex gap-3 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
          <select 
            className="bg-black text-white px-4 py-3 rounded-xl outline-none font-bold text-xs"
            value={filterEmpresa}
            onChange={(e) => setFilterEmpresa(e.target.value as any)}
          >
            <option value="TODAS">TODAS AS EMPRESAS</option>
            <option value={Empresa.CAMPLUVAS}>CAMPLUVAS</option>
            <option value={Empresa.LOCATEX}>LOCATEX</option>
          </select>

          <select 
            className="bg-black text-white px-4 py-3 rounded-xl outline-none font-bold text-xs"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
          >
            <option value="TODOS">TODOS STATUS</option>
            <option value={Status.VIGENTE}>VIGENTE</option>
            <option value={Status.PENDENTE}>PENDENTE</option>
            <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
            <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
          </select>

          <button 
            onClick={() => setShowExportModal(true)}
            className="flex items-center gap-2 bg-black text-[#FFA200] px-6 py-3 rounded-xl font-bold hover:bg-gray-900 transition-all shadow-lg text-xs shrink-0"
          >
            <Download size={16} />
            EXPORTAR
          </button>
        </div>
      </div>

      <div className="grid gap-4">
        {filtered.length === 0 ? (
          <div className="bg-white/40 p-12 rounded-3xl text-center border-2 border-dashed border-black/10">
            <AlertCircle className="w-12 h-12 text-black/40 mx-auto mb-4" />
            <p className="text-xl font-bold text-black/60 italic">Nenhuma obrigação encontrada</p>
          </div>
        ) : (
          filtered.map(o => (
            <div 
              key={o.id} 
              className="bg-white rounded-3xl p-6 shadow-sm border border-transparent hover:border-black/10 transition-all group overflow-hidden relative"
            >
              <div className={`absolute left-0 top-0 bottom-0 w-2 ${STATUS_COLORS[o.status]}`} />

              <div className="flex flex-col lg:flex-row justify-between gap-6">
                <div className="flex-1 space-y-4">
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <span className={`text-[10px] font-black px-2 py-0.5 rounded text-white ${STATUS_COLORS[o.status]}`}>
                          {o.status}
                        </span>
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{o.periodicidade}</span>
                      </div>
                      <h3 className="text-xl font-black italic text-black uppercase">{o.nomeDocumento}</h3>
                      <p className="text-sm font-medium text-gray-500">{o.tipo} - {o.numeroDocumento}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><Building2 size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Órgão / Empresa</p>
                        <p className="font-bold text-black truncate">{o.orgao} / {o.empresa}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><Calendar size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Providências</p>
                        <p className="font-bold text-black">{formatDate(o.dataInicio)} - {formatDate(o.dataFinal)}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><User size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Responsável</p>
                        <p className="font-bold text-black truncate">{o.responsavel || 'Não definido'}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <div className="bg-gray-100 p-2 rounded-lg"><AlertCircle size={16} /></div>
                      <div>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Validade</p>
                        <p className="font-bold text-black">{formatDate(o.validadeDocumento)}</p>
                      </div>
                    </div>
                    {o.dataConclusao && (
                      <div className="flex items-center gap-2 text-sm">
                        <div className="bg-green-50 p-2 rounded-lg text-green-600"><CheckCircle2 size={16} /></div>
                        <div>
                          <p className="text-[10px] font-bold text-gray-400 uppercase">Concluído em</p>
                          <p className="font-bold text-black">{formatDate(o.dataConclusao)}</p>
                        </div>
                      </div>
                    )}
                  </div>

                  {o.observacoes && (
                    <div className="mt-4 p-4 bg-gray-50 rounded-2xl border-l-4 border-black/10">
                      <p className="text-xs font-bold text-gray-400 uppercase mb-1">Observações</p>
                      <p className="text-sm text-gray-700">{o.observacoes}</p>
                    </div>
                  )}
                </div>

                <div className="flex flex-row lg:flex-col items-center justify-end gap-2 shrink-0 no-print">
                  <select 
                    value={o.status}
                    onChange={(e) => onUpdate(o.id, { status: e.target.value as Status })}
                    className="bg-black text-white text-xs font-bold p-3 rounded-xl border-none outline-none appearance-none cursor-pointer"
                  >
                    <option value={Status.VIGENTE}>VIGENTE</option>
                    <option value={Status.PENDENTE}>PENDENTE</option>
                    <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
                    <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
                  </select>

                  <div className="flex gap-2 w-full lg:w-auto">
                    <button 
                      type="button"
                      onClick={() => setEditingItem(o)}
                      className="flex-1 lg:flex-none p-3 bg-gray-100 text-gray-600 rounded-xl hover:bg-black hover:text-[#FFA200] transition-all"
                      title="Editar"
                    >
                      <Pencil size={20} />
                    </button>
                    <button 
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        if(confirm('Tem certeza que deseja excluir esta obrigação permanentemente?')) {
                          onDelete(o.id);
                        }
                      }}
                      className="flex-1 lg:flex-none p-3 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all shadow-sm"
                      title="Excluir"
                    >
                      <Trash2 size={20} />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-2xl font-black italic uppercase tracking-tighter">Exportar Relatório</h3>
              <button onClick={() => setShowExportModal(false)} className="p-2 hover:bg-gray-100 rounded-full">
                <X size={24} />
              </button>
            </div>

            <p className="text-sm text-gray-500 mb-6">Selecione o período de vencimento para filtrar os dados do relatório.</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
              <div>
                <label className="block text-[10px] font-bold uppercase mb-2 text-gray-400">Data Inicial</label>
                <input 
                  type="date" 
                  className="w-full bg-black text-white p-3 rounded-xl outline-none focus:ring-2 ring-[#FFA200] transition-all"
                  value={exportRange.start}
                  onChange={(e) => setExportRange(prev => ({ ...prev, start: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold uppercase mb-2 text-gray-400">Data Final</label>
                <input 
                  type="date" 
                  className="w-full bg-black text-white p-3 rounded-xl outline-none focus:ring-2 ring-[#FFA200] transition-all"
                  value={exportRange.end}
                  onChange={(e) => setExportRange(prev => ({ ...prev, end: e.target.value }))}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              <button 
                onClick={handleExportExcel}
                className="flex items-center justify-center gap-3 p-4 bg-green-600 text-white rounded-2xl font-black hover:bg-green-700 transition-all"
              >
                <FileSpreadsheet size={24} />
                EXPORTAR PARA EXCEL (.xlsx)
              </button>
              <button 
                onClick={handleExportPDF}
                className="flex items-center justify-center gap-3 p-4 bg-red-600 text-white rounded-2xl font-black hover:bg-red-700 transition-all"
              >
                <FilePieChart size={24} />
                GERAR RELATÓRIO PDF
              </button>
            </div>

            <button 
              onClick={() => { setExportRange({start: '', end: ''}); handleExportExcel(); }}
              className="w-full mt-4 text-xs font-bold text-gray-400 hover:text-black uppercase underline"
            >
              Exportar todas as obrigações (sem filtro)
            </button>
          </div>
        </div>
      )}

      {/* Edit Modal */}
      {editingItem && (
        <EditObligationModal 
          obligation={editingItem} 
          onClose={() => setEditingItem(null)} 
          onSave={(updated) => {
            onUpdate(editingItem.id, updated);
            setEditingItem(null);
          }} 
        />
      )}
    </div>
  );
};

export default ObligationList;

import React, { useState } from 'react';
import { X, Save, Plus } from 'lucide-react';
import { Obligation, Status, Empresa } from '../types';
import { INITIAL_ORGAOS, INITIAL_PERIODICITIES, INITIAL_RESPONSAVEIS } from '../constants';

interface EditObligationModalProps {
  obligation: Obligation;
  onClose: () => void;
  onSave: (updated: Partial<Obligation>) => void;
}

const EditObligationModal: React.FC<EditObligationModalProps> = ({ obligation, onClose, onSave }) => {
  const [formData, setFormData] = useState<Partial<Obligation>>(obligation);
  const [periodicities, setPeriodicities] = useState(INITIAL_PERIODICITIES);
  const [orgaos, setOrgaos] = useState(INITIAL_ORGAOS);
  const [responsaveis, setResponsaveis] = useState(INITIAL_RESPONSAVEIS);
  const [showAddModal, setShowAddModal] = useState<'periodicidade' | 'orgao' | 'responsavel' | null>(null);
  const [newItemValue, setNewItemValue] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleAddNewItem = () => {
    if (!newItemValue.trim() || !showAddModal) return;

    if (showAddModal === 'periodicidade') {
      setPeriodicities(prev => [...prev, newItemValue]);
      setFormData(prev => ({ ...prev, periodicidade: newItemValue }));
    } else if (showAddModal === 'orgao') {
      setOrgaos(prev => [...prev, newItemValue]);
      setFormData(prev => ({ ...prev, orgao: newItemValue }));
    } else {
      setResponsaveis(prev => [...prev, newItemValue]);
      setFormData(prev => ({ ...prev, responsavel: newItemValue }));
    }
    setNewItemValue('');
    setShowAddModal(null);
  };

  const inputClass = "w-full bg-black text-white border-2 border-transparent focus:border-[#FFA200] p-3 rounded-lg outline-none transition-all text-sm";
  const labelClass = "block text-[10px] font-bold uppercase tracking-wider mb-1 text-gray-500";

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150] flex items-center justify-center p-4">
      <div className="bg-white rounded-[40px] w-full max-w-4xl max-h-[90vh] overflow-y-auto p-8 md:p-12 shadow-2xl animate-in slide-in-from-bottom-8 duration-300">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-3xl font-black italic uppercase tracking-tighter">Editar Obrigação</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X size={28} />
          </button>
        </div>

        <form onSubmit={(e) => { e.preventDefault(); onSave(formData); }} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

            <div className="relative">
              <label className={labelClass}>Periodicidade</label>
              <div className="flex gap-2">
                <select name="periodicidade" value={formData.periodicidade} onChange={handleChange} className={inputClass}>
                  {periodicities.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
                <button type="button" onClick={() => setShowAddModal('periodicidade')} className="bg-black text-[#FFA200] p-3 rounded-lg"><Plus size={16} /></button>
              </div>
            </div>

            <div className="relative">
              <label className={labelClass}>Órgão</label>
              <div className="flex gap-2">
                <select name="orgao" value={formData.orgao} onChange={handleChange} className={inputClass}>
                  {orgaos.map(o => <option key={o} value={o}>{o}</option>)}
                </select>
                <button type="button" onClick={() => setShowAddModal('orgao')} className="bg-black text-[#FFA200] p-3 rounded-lg"><Plus size={16} /></button>
              </div>
            </div>

            <div>
              <label className={labelClass}>Empresa</label>
              <select name="empresa" value={formData.empresa} onChange={handleChange} className={inputClass}>
                <option value={Empresa.CAMPLUVAS}>CAMPLUVAS</option>
                <option value={Empresa.LOCATEX}>LOCATEX</option>
              </select>
            </div>

            <div>
              <label className={labelClass}>Início das Providências</label>
              <input type="date" name="dataInicio" value={formData.dataInicio} onChange={handleChange} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Final das Providências</label>
              <input type="date" name="dataFinal" value={formData.dataFinal} onChange={handleChange} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Validade do Documento</label>
              <input type="date" name="validadeDocumento" value={formData.validadeDocumento} onChange={handleChange} className={inputClass} />
            </div>

            <div>
              <label className={labelClass}>Tipo</label>
              <input type="text" name="tipo" value={formData.tipo} onChange={handleChange} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Nº do Documento</label>
              <input type="text" name="numeroDocumento" value={formData.numeroDocumento} onChange={handleChange} className={inputClass} />
            </div>
            <div className="relative">
              <label className={labelClass}>Responsável</label>
              <div className="flex gap-2">
                <select name="responsavel" value={formData.responsavel} onChange={handleChange} className={inputClass}>
                  {responsaveis.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
                <button type="button" onClick={() => setShowAddModal('responsavel')} className="bg-black text-[#FFA200] p-3 rounded-lg"><Plus size={16} /></button>
              </div>
            </div>

            <div className="md:col-span-2">
              <label className={labelClass}>Nome do Documento</label>
              <input type="text" name="nomeDocumento" value={formData.nomeDocumento} onChange={handleChange} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Status</label>
              <select name="status" value={formData.status} onChange={handleChange} className={inputClass}>
                <option value={Status.VIGENTE}>VIGENTE</option>
                <option value={Status.PENDENTE}>PENDENTE</option>
                <option value={Status.EM_ANDAMENTO}>EM ANDAMENTO</option>
                <option value={Status.CONCLUIDO}>CONCLUÍDO</option>
              </select>
            </div>

            <div className="md:col-span-2">
              <label className={labelClass}>Ação</label>
              <input type="text" name="acao" value={formData.acao} onChange={handleChange} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Data de conclusão</label>
              <input type="date" name="dataConclusao" value={formData.dataConclusao} onChange={handleChange} className={inputClass} />
            </div>
          </div>

          <div>
            <label className={labelClass}>Observações</label>
            <textarea name="observacoes" value={formData.observacoes} onChange={handleChange} className={`${inputClass} min-h-[100px] resize-none`} />
          </div>

          <div className="flex justify-end gap-4 pt-4 border-t border-gray-100">
            <button type="button" onClick={onClose} className="px-8 py-3 font-bold text-gray-500 hover:text-black transition-colors">
              Cancelar
            </button>
            <button type="submit" className="px-12 py-3 bg-black text-[#FFA200] font-black italic rounded-xl hover:shadow-xl transition-all flex items-center gap-2">
              <Save size={20} />
              ATUALIZAR DADOS
            </button>
          </div>
        </form>

        {showAddModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl p-8 w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-4 uppercase italic">Cadastrar {showAddModal}</h3>
              <input autoFocus type="text" value={newItemValue} onChange={(e) => setNewItemValue(e.target.value)} className="w-full bg-black text-white p-3 rounded-lg mb-6 outline-none" placeholder="..." />
              <div className="flex justify-end gap-3">
                <button onClick={() => setShowAddModal(null)} className="px-4 py-2 font-bold text-gray-400">Fechar</button>
                <button onClick={handleAddNewItem} className="px-6 py-2 bg-black text-[#FFA200] font-black rounded-lg">ADICIONAR</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default EditObligationModal;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { 
  ClipboardCheck, 
  LayoutDashboard, 
  PlusCircle, 
  ListTodo,
