};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { 
  LayoutDashboard, 
  PlusCircle, 
  ListTodo,
  ShieldCheck,
  Menu,
  X,
  Building2,
  Users
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import ObligationForm from './components/ObligationForm';
import ObligationList from './components/ObligationList';
import OrgaoManager from './components/OrgaoManager';
import ResponsavelManager from './components/ResponsavelManager';
import { Obligation } from './types';

const App: React.FC = () => {
  const [obligations, setObligations] = useState<Obligation[]>(() => {
    const saved = localStorage.getItem('eco_obligations');
    return saved ? JSON.parse(saved) : [];
  });

  const [orgaos, setOrgaos] = useState<string[]>(() => {
    const saved = localStorage.getItem('eco_orgaos');
    return saved ? JSON.parse(saved) : [];
  });

  const [responsaveis, setResponsaveis] = useState<string[]>(() => {
    const saved = localStorage.getItem('eco_responsaveis');
    return saved ? JSON.parse(saved) : [];
  });

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('eco_obligations', JSON.stringify(obligations));
  }, [obligations]);

  useEffect(() => {
    localStorage.setItem('eco_orgaos', JSON.stringify(orgaos));
  }, [orgaos]);

  useEffect(() => {
    localStorage.setItem('eco_responsaveis', JSON.stringify(responsaveis));
  }, [responsaveis]);

  const addObligation = (newObligation: Obligation) => {
    setObligations(prev => [newObligation, ...prev]);
  };

  const deleteObligation = (id: string) => {
    setObligations(prev => prev.filter(o => o.id !== id));
  };

  const updateObligation = (id: string, updated: Partial<Obligation>) => {
    setObligations(prev => prev.map(o => o.id === id ? { ...o, ...updated } : o));
  };

  return (
    <Router>
      <div className="min-h-screen flex flex-col md:flex-row overflow-hidden" style={{ backgroundColor: '#FFA200' }}>

        {/* Mobile Toggle */}
        <div className="md:hidden bg-black text-white p-4 flex justify-between items-center shadow-lg">
          <div className="flex items-center gap-2">
            <ShieldCheck className="text-[#FFA200]" />
            <span className="font-bold tracking-tight">EcoGuard SGA</span>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
            {isSidebarOpen ? <X /> : <Menu />}
          </button>
        </div>

        {/* Sidebar */}
        <aside className={`
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
          md:translate-x-0 fixed md:static inset-y-0 left-0 z-50
          w-64 bg-black text-white transition-transform duration-300 ease-in-out
          flex flex-col shadow-2xl border-r border-black/10
        `}>
          <div className="p-8 hidden md:flex flex-col items-center border-b border-white/10">
            <div className="bg-[#FFA200] p-3 rounded-2xl mb-4">
              <ShieldCheck className="w-8 h-8 text-black" />
            </div>
            <h1 className="text-xl font-black italic tracking-tighter">ECOGUARD</h1>
            <p className="text-[10px] text-gray-400 font-medium tracking-[0.2em] uppercase">Gestão Ambiental</p>
          </div>

          <nav className="flex-1 p-6 space-y-2">
            <Link 
              to="/" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#FFA200]/10 hover:text-[#FFA200] transition-all group"
            >
              <LayoutDashboard className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Dashboard</span>
            </Link>

            <Link 
              to="/orgaos" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#FFA200]/10 hover:text-[#FFA200] transition-all group"
            >
              <Building2 className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Órgãos</span>
            </Link>

            <Link 
              to="/responsaveis" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#FFA200]/10 hover:text-[#FFA200] transition-all group"
            >
              <Users className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Responsáveis</span>
            </Link>

            <div className="py-2 border-b border-white/5 my-2" />

            <Link 
              to="/cadastro" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#FFA200]/10 hover:text-[#FFA200] transition-all group"
            >
              <PlusCircle className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Nova Obrigação</span>
            </Link>

            <Link 
              to="/listagem" 
              onClick={() => setIsSidebarOpen(false)}
              className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#FFA200]/10 hover:text-[#FFA200] transition-all group"
            >
              <ListTodo className="w-5 h-5 transition-transform group-hover:scale-110" />
              <span className="font-medium">Obrigações</span>
            </Link>
          </nav>

          <div className="p-6 text-center text-[10px] text-gray-500">
            v1.1.0 &copy; {new Date().getFullYear()} EcoGuard
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-6xl mx-auto">
            <Routes>
              <Route path="/" element={<Dashboard obligations={obligations} onDelete={deleteObligation} onUpdate={updateObligation} orgaos={orgaos} responsaveis={responsaveis} />} />
              <Route path="/orgaos" element={<OrgaoManager items={orgaos} setItems={setOrgaos} />} />
              <Route path="/responsaveis" element={<ResponsavelManager items={responsaveis} setItems={setResponsaveis} />} />
              <Route path="/cadastro" element={<ObligationForm onSave={addObligation} orgaos={orgaos} responsaveis={responsaveis} />} />
              <Route path="/listagem" element={<ObligationList obligations={obligations} onDelete={deleteObligation} onUpdate={updateObligation} orgaos={orgaos} responsaveis={responsaveis} />} />
            </Routes>
          </div>
        </main>
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { Plus, Trash2, Building2, ShieldAlert } from 'lucide-react';

interface ManagerProps {
  items: string[];
  setItems: (items: string[]) => void;
}

const OrgaoManager: React.FC<ManagerProps> = ({ items, setItems }) => {
  const [newValue, setNewValue] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newValue.trim()) return;
    if (items.includes(newValue.trim().toUpperCase())) {
      alert('Este órgão já está cadastrado.');
      return;
    }
    setItems([...items, newValue.trim().toUpperCase()]);
    setNewValue('');
  };

  const handleRemove = (item: string) => {
    if (window.confirm(`Deseja remover o órgão "${item}"?`)) {
      setItems(items.filter(i => i !== item));
    }
  };

  return (
    <div className="bg-white/40 backdrop-blur-md rounded-3xl p-6 md:p-10 shadow-xl border border-white/50 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center gap-3 mb-8">
        <div className="bg-black p-3 rounded-2xl">
          <Building2 className="text-[#FFA200]" />
        </div>
        <h2 className="text-3xl font-black italic text-black uppercase tracking-tighter">Gestão de Órgãos</h2>
      </div>

      <form onSubmit={handleAdd} className="mb-8">
        <label className="block text-[11px] font-bold uppercase tracking-wider mb-2 text-black/80">Novo Órgão Ambiental</label>
        <div className="flex gap-3">
          <input 
            type="text" 
            value={newValue}
            onChange={(e) => setNewValue(e.target.value)}
            placeholder="Ex: IBAMA, CETESB, PREFEITURA..."
            className="flex-1 bg-black text-white p-4 rounded-xl outline-none border-2 border-transparent focus:border-white transition-all uppercase font-bold"
          />
          <button 
            type="submit"
            className="bg-black text-[#FFA200] px-8 rounded-xl font-black italic hover:shadow-lg transition-all flex items-center gap-2"
          >
            <Plus size={24} />
            CADASTRAR
          </button>
        </div>
      </form>

      <div className="space-y-3">
        <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-4">Órgãos Cadastrados ({items.length})</h3>
        {items.length === 0 ? (
