    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Obrigações');
    XLSX.writeFile(workbook, `Relatorio_Obrigacoes_${new Date().toISOString().split('T')[0]}.xlsx`);
    setShowExportModal(false);
